쿼리 작성: SELECT AVG(CASE WHEN TIMESTAMPDIFF(HOUR, review_creation_date, review_answer_timestamp) <= 48 THEN 1.0 ELSE 0.0 END) AS within_48h_ratio
FROM order_reviews
WHERE review_answer_timestamp >= '2017-07-01' AND review_answer_timestamp < '2018-01-01';

